views['admin-topup']=()=>`<div class="bc"><a href="#" data-v="home">หน้าหลัก</a> &nbsp;/&nbsp; <a href="#" data-v="admin">ห้องแอดมิน</a> &nbsp;/&nbsp; จัดการเติมเงิน</div><h1 class="tp-h">จัดการเติมเงิน</h1><div class="btns" id="admp">${ADMT.map((c,i)=>`<a href="#" class="bt" data-adm="t${i}"><svg viewBox="0 0 60 60">${c[3]}</svg><span class="t"><span class="t1">${c[0]}</span><span class="t2" style="font-size:${c[2]}px">${c[1]}</span></span></a>`).join('')}</div>`; // ADMIN
document.addEventListener('click',e=>{const el=e.target.closest('[data-adm]');if(!el)return;e.preventDefault();if(!isAdm())return;if(el.dataset.adm==='0')show('admin-prod');else if(el.dataset.adm==='p0')show('admin-add');else if(el.dataset.adm==='p1')show('admin-edit');else if(el.dataset.adm==='p2')show('admin-stock');else if(el.dataset.adm==='1')show('admin-cat');else if(el.dataset.adm==='2')show('admin-topup');else if(el.dataset.adm==='5')show('admin-acc');else if(el.dataset.adm==='6')show('admin-sales');else if(el.dataset.adm==='4')show('admin-set');else if(el.dataset.adm==='3')show('admin-agent');else tpToast('ຍັງບໍ່ເປີດໃຊ້ງານ') /* p0=เพิ่มสินค้า p1=แก้ไขสินค้า p2=เติมสต็อก: หน้าปลายทางยังว่าง */}); // ADMIN: ยังไม่มีหน้าปลายทางของเพิ่ม/แก้ไขสินค้า
// ===== ADMIN: เพิ่ม / แก้ไข / เติมสต็อกสินค้า (ตาราง products, stock_items ใน Supabase PXPSHOP) =====
let AD={},ADL=[],ADS=[];
const adIc='<svg viewBox="0 0 24 24"><path d="M12 16V4M7 9l5-5 5 5M4 16v3a1 1 0 001 1h14a1 1 0 001-1v-3"/></svg>';
const adBc=t=>`<div class="bc"><a href="#" data-v="home">หน้าหลัก</a> &nbsp;/&nbsp; <a href="#" data-v="admin">ห้องแอดมิน</a> &nbsp;/&nbsp; <a href="#" data-v="admin-prod">จัดการสินค้า</a> &nbsp;/&nbsp; ${t}</div>`;
const adThumb=p=>`<div class="ph">${p.image_url?`<img src="${esc(p.image_url)}" alt="">`:PH}</div>`;
const adErr=l=>{l.innerHTML='<div class="hs-em">โหลดไม่สำเร็จ</div>';tr(l)};
async function adFetch(c){const r=await sb.from('products').select(c).order('created_at',{ascending:false});if(r.error)throw r.error;return r.data||[]}
// --- แก้ไขสินค้า: รายการ
views['admin-edit']=()=>adBc('แก้ไขสินค้า')+`<h1 class="tp-h">แก้ไขสินค้า</h1><div id="adel"><div class="hs-em">กำลังโหลด...</div></div>${(setTimeout(adeLoad),'')}`; // ADMIN
function adRow(p){const s=p.update_mode===true?'upd':p.sales_closed===true?'off':pout(pm(p))?'out':'';return `<div class="tp-card ad-sh ad-pr" data-id="${p.id}"><a href="#" class="ad-pm" data-v="admin-add" data-m="${p.id}">${adThumb(p)}<div><b>${esc(p.name)}</b><small>${tpf(Number(p.price))} กีบ · คงเหลือ ${p.stock}${p.is_active?'':' · ซ่อนอยู่'}</small>${s?`<em class="ad-ch ${s}">${PSL[s]}</em>`:''}</div></a><div class="ad-tg"><label><span>อัปเดต</span><button type="button" class="ad-sw ad-sm u${p.update_mode===true?' on':''}" data-k="update_mode" data-id="${p.id}" role="switch" aria-checked="${p.update_mode===true}"><i></i></button></label><label><span>เปิดขาย</span><button type="button" class="ad-sw ad-sm${p.sales_closed===true?'':' on'}" data-k="sales_closed" data-id="${p.id}" role="switch" aria-checked="${p.sales_closed!==true}"><i></i></button></label></div><a href="#" class="ct-go ad-cv" data-v="admin-add" data-m="${p.id}"><svg viewBox="0 0 24 24"><path d="M9 5l7 7-7 7"/></svg></a></div>`} // ADMIN
async function adeLoad(){const l=$('#adel');if(!l||!sb)return;try{ADL=await adFetch('*');l.innerHTML=ADL.length?ADL.map(adRow).join(''):hsEmpty;tr(l)}catch(_){adErr(l)}} // ADMIN
function adSync(p){const r=document.querySelector('.ad-pr[data-id="'+p.id+'"]');if(!r)return;const s=p.update_mode===true?'upd':p.sales_closed===true?'off':pout(pm(p))?'out':'',d=r.querySelector('.ad-pm div'),o=d.querySelector('.ad-ch');if(o)o.remove();if(s){d.insertAdjacentHTML('beforeend',`<em class="ad-ch ${s}">${PSL[s]}</em>`);tr(d)}r.querySelectorAll('.ad-sw').forEach(x=>{const on=x.dataset.k==='update_mode'?p.update_mode===true:p.sales_closed!==true;x.classList.toggle('on',on);x.setAttribute('aria-checked',String(on))})} // ADMIN
document.addEventListener('click',async e=>{const b=e.target.closest('.ad-tg .ad-sw');if(!b)return;e.preventDefault();if(!isAdm()||!sb||b.dataset.busy)return;const k=b.dataset.k,p=ADL.find(x=>String(x.id)===b.dataset.id);if(!p)return;const old=p[k]===true,nv=!old;p[k]=nv;b.dataset.busy='1';adSync(p);
try{const r=await sb.from('products').update({[k]:nv}).eq('id',p.id).select('id');if(r.error||!r.data||!r.data.length)throw r.error||new Error('no_permission');const q=P.find(x=>x[0]===p.id);if(q)q[k==='update_mode'?11:10]=nv;tpToast(k==='update_mode'?(nv?'เปิดโหมดอัปเดตแล้ว':'ปิดโหมดอัปเดตแล้ว'):(nv?'ปิดขายสินค้าแล้ว':'เปิดขายสินค้าแล้ว'))}
catch(x){p[k]=old;adSync(p);tpToast('บันทึกไม่สำเร็จ'+(x&&x.message?' ['+x.message+']':''))}finally{delete b.dataset.busy}}); // ADMIN: สวิตช์ 1 = โหมดอัปเดต (products.update_mode) · สวิตช์ 2 = เปิด/ปิดขาย (products.sales_closed)
// --- เพิ่ม/แก้ไขสินค้า: ฟอร์ม (m = id สินค้า → โหมดแก้ไข)
views['admin-add']=m=>{const e=ADL.find(x=>x.id===m),o=e&&Array.isArray(e.options)?e.options:[];
AD={f:null,id:e?e.id:null,cat:e&&e.category_id||'',catOk:false,old:e&&e.image_url||'',rm:false,act:e?e.is_active:true,dur:o.length>0,pk:o.length?o.map(x=>({d:x.d||'',h:x.h||'',p:x.p||''})):[{d:'',h:'',p:''}]};
return adBc(e?'แก้ไขสินค้า':'เพิ่มสินค้า')+`<h1 class="tp-h">${e?'แก้ไขสินค้า':'เพิ่มสินค้า'}</h1>
<div class="tp-card"><h2>รูปสินค้า</h2><label class="tp-up ad-up${AD.old?' has':''}"><input class="ad-fi" type="file" accept="image/*" hidden><img class="tp-pv" alt=""${AD.old?` src="${esc(AD.old)}"`:''}><button class="ad-rm" type="button" aria-label="x">✕</button><span class="tp-t">${adIc}<span>แตะเพื่อเลือกรูปสินค้า</span></span></label></div>
<div class="tp-card"><h2>ชื่อสินค้า</h2><input class="ad-in" id="adn" maxlength="80" autocomplete="off" placeholder="ชื่อสินค้า" value="${e?esc(e.name):''}"></div>
<div class="tp-card"><h2>เลือกหมวดหมู่ของสินค้า</h2><select class="ad-in" id="adcat"><option value="">ไม่ระบุหมวดหมู่</option></select></div>
<div class="tp-card" id="adpc"${AD.dur?' hidden':''}><h2>ตั้งราคา</h2><div class="ad-pw"><input class="ad-in" id="adp" inputmode="numeric" autocomplete="off" placeholder="0" value="${e&&!AD.dur?Number(e.price):''}"><span>กีบ</span></div></div>
<div class="tp-card"><div class="ad-sr"><div><h2>ขายสินค้าแบบระยะเวลา</h2><small>ตั้งราคาและจำนวนวัน/ชั่วโมงเองได้</small></div><button type="button" class="ad-sw${AD.dur?' on':''}" id="addur" role="switch" aria-checked="${AD.dur}"><i></i></button></div><div class="ad-pk${AD.dur?' on':''}" id="adpk"></div></div>
<div class="tp-card"><h2>รายละเอียดสินค้า</h2><textarea class="ad-ta" id="add" maxlength="1000" placeholder="อธิบายสินค้า">${e?esc(e.description||''):''}</textarea></div>
${e?`<div class="tp-card"><div class="ad-sr"><div><h2>แสดงสินค้าในร้าน</h2><small>ปิดเพื่อซ่อนสินค้าจากลูกค้า</small></div><button type="button" class="ad-sw${AD.act?' on':''}" id="adact" role="switch"><i></i></button></div></div>`:''}
<button class="tp-cta" id="adgo">${e?'บันทึกการแก้ไข':'บันทึกสินค้า'}</button>${e?'<button class="ad-del" id="addel" type="button">ลบสินค้า</button>':''}${(setTimeout(adPk),setTimeout(acOpts),'')}`}; // ADMIN
function adPk(){const l=$('#adpk');if(!l)return;const ip=(i,k,v)=>`<input inputmode="numeric" data-i="${i}" data-k="${k}" value="${v}" placeholder="0" autocomplete="off">`;
l.innerHTML=AD.pk.map((x,i)=>`<div class="ad-pc"><button type="button" class="ad-x" data-i="${i}" aria-label="x"${AD.pk.length<2?' hidden':''}>✕</button><div class="ad-tm"><label>${ip(i,'d',x.d)}<span>วัน</span></label><label>${ip(i,'h',x.h)}<span>ชม.</span></label></div><label class="ad-pp">${ip(i,'p',x.p)}<span>กีบ</span></label></div>`).join('')+(AD.pk.length<8?'<button type="button" class="ad-add"><b>+</b>เพิ่มแพ็กเกจ</button>':'');tr(l)}
function adImg(f){const im=new Image(),u=URL.createObjectURL(f);im.onload=()=>{const k=Math.min(1,1000/Math.max(im.width,im.height)),c=document.createElement('canvas'),x=c.getContext('2d');c.width=Math.round(im.width*k);c.height=Math.round(im.height*k);x.fillStyle='#fff';x.fillRect(0,0,c.width,c.height);x.drawImage(im,0,0,c.width,c.height);c.toBlob(b=>{URL.revokeObjectURL(u);if(!b)return tpToast('ไฟล์รูปไม่ถูกต้อง');AD.f=b;AD.rm=false;$('.ad-up .tp-pv').src=URL.createObjectURL(b);$('.ad-up').classList.add('has')},'image/jpeg',.85)};im.onerror=()=>tpToast('ไฟล์รูปไม่ถูกต้อง');im.src=u}
async function adSave(){const g=$('#adgo'),name=$('#adn').value.trim(),lb=AD.id?'บันทึกการแก้ไข':'บันทึกสินค้า';let price=0,opts=[];
if(!name)return tpToast('กรุณาใส่ชื่อสินค้า');
if(AD.dur){opts=AD.pk.map(x=>({d:+x.d||0,h:+x.h||0,p:+x.p||0}));if(opts.some(o=>(!o.d&&!o.h)||!o.p))return tpToast('กรอกวัน/ชม. และราคาของแพ็กเกจให้ครบ');price=Math.min(...opts.map(o=>o.p))}
else{price=parseInt($('#adp').value)||0;if(!price)return tpToast('กรุณาตั้งราคา')}
if(!sb||!isAdm())return;g.disabled=true;g.textContent='กำลังบันทึก...';tr(g);
try{let url=AD.rm?null:(AD.old||null);if(AD.f){const path=Date.now()+'_'+Math.random().toString(36).slice(2,8)+'.jpg',u=await sb.storage.from('product-images').upload(path,AD.f,{contentType:'image/jpeg'});if(u.error)throw u.error;url=sb.storage.from('product-images').getPublicUrl(path).data.publicUrl}
const row={name,image_url:url,price,description:$('#add').value.trim()||null,options:opts};if(AD.catOk)row.category_id=AD.cat||null;let r;
if(AD.id){row.is_active=AD.act;r=await sb.from('products').update(row).eq('id',AD.id)}else r=await sb.from('products').insert(row);
if(r.error)throw r.error;okPop(AD.id?'บันทึกการแก้ไขสำเร็จ':'เพิ่มสินค้าสำเร็จ');await loadProds();show('admin-prod')}
catch(x){g.disabled=false;g.textContent=lb;tr(g);tpToast('บันทึกไม่สำเร็จ'+(x&&x.message?' ['+x.message+']':''))}}
async function adDel(){if(!AD.id||!sb||!isAdm()||!confirm(trs('ลบสินค้านี้ใช่ไหม?')))return;try{const r=await sb.from('products').delete().eq('id',AD.id);if(r.error)throw r.error;tpToast('ลบสินค้าแล้ว');await loadProds();show('admin-prod')}catch(x){tpToast('ลบไม่สำเร็จ'+(x&&x.message?' ['+x.message+']':''))}}
document.addEventListener('change',e=>{if(!e.target.classList.contains('ad-fi'))return;const f=e.target.files[0];if(f)adImg(f)}); // ADMIN
document.addEventListener('input',e=>{const t=e.target;if(t.id==='adp'){t.value=t.value.replace(/\D/g,'').slice(0,9);return}
if(t.closest('.ad-pc')&&t.dataset.k){t.value=t.value.replace(/\D/g,'').slice(0,t.dataset.k==='p'?9:4);AD.pk[+t.dataset.i][t.dataset.k]=t.value;return}
if(t.classList.contains('ad-sta')){AS.t=t.value;const n=adLines(t.value).length,c=t.closest('.ad-sk').querySelector('.ad-cnt');c.textContent=n+' ชิ้น';tr(c)}}); // ADMIN
document.addEventListener('click',e=>{const t=e.target;
if(t.closest('.ad-rm')){e.preventDefault();e.stopPropagation();AD.f=null;AD.rm=true;AD.old='';$('.ad-fi').value='';$('.ad-up .tp-pv').removeAttribute('src');$('.ad-up').classList.remove('has');return}
const sw=t.closest('.ad-sw');if(sw){if(sw.id==='adact'){AD.act=!AD.act;sw.classList.toggle('on',AD.act);return}AD.dur=!AD.dur;sw.classList.toggle('on',AD.dur);sw.setAttribute('aria-checked',AD.dur);$('#adpk').classList.toggle('on',AD.dur);$('#adpc').hidden=AD.dur;return}
if(t.closest('.ad-add')){if(AD.pk.length<8){AD.pk.push({d:'',h:'',p:''});adPk()}return}
const x=t.closest('.ad-x');if(x){if(AD.pk.length>1){AD.pk.splice(+x.dataset.i,1);adPk()}return}
if(t.closest('#addel')){adDel();return}
if(t.closest('#adgo'))adSave()}); // ADMIN
// --- เติมสต็อก: วางรหัส/ลิงก์/บัญชี 1 บรรทัด = 1 ชิ้น เก็บในตาราง stock_items (สต็อกคงเหลือซิงก์อัตโนมัติด้วย trigger)
const adLines=v=>[...new Set(v.split('\n').map(x=>x.trim()).filter(Boolean))];
views['admin-stock']=()=>adBc('เติมสต็อก')+`<h1 class="tp-h">เติมสต็อก</h1><div id="adsl"><div class="hs-em">กำลังโหลด...</div></div>${(setTimeout(adsLoad),'')}`; // ADMIN
let AS={p:null,o:0,t:''};
const adsOpts=p=>Array.isArray(p.options)?p.options:[],adsN=(p,i)=>((p.option_stock||{})[i])|0;
function adsR(){const l=$('#adsl'),p=ADS.find(x=>x.id===AS.p);if(!l||!p)return;const o=adsOpts(p);if(AS.o>=o.length)AS.o=0;const ob=o.length?optLbl(o[AS.o]):null;
l.innerHTML=`<div class="tp-card"><h2>เลือกสินค้า</h2><select class="ad-in" id="ass">${ADS.map(x=>`<option value="${x.id}"${x.id===p.id?' selected':''}>${esc(x.name)}</option>`).join('')}</select></div>
${o.length?`<div class="tp-card"><h2>เลือกระยะเวลา</h2><div class="or-ops">${o.map((x,i)=>{const b=optLbl(x);return `<button type="button" class="as-op${i===AS.o?' on':''}" data-i="${i}"><span class="n">${b.n}</span><span class="u">${b.u}</span><span class="p">เหลือ ${adsN(p,i)} ชิ้น</span></button>`}).join('')}</div></div>`:''}
<div class="tp-card ad-sk"><div class="ad-sh">${adThumb(p)}<div><b>${esc(p.name)}${ob?' · '+ob.n+' '+ob.u:''}</b><small>คงเหลือ <i>${o.length?adsN(p,AS.o):p.stock}</i> ชิ้น · ขายแล้ว ${p.sold}</small></div></div><textarea class="ad-ta ad-sta" placeholder="วางรหัสสินค้า 1 บรรทัดต่อ 1 ชิ้น">${esc(AS.t)}</textarea><div class="ad-sa"><span class="ad-cnt">${adLines(AS.t).length} ชิ้น</span><button type="button" class="ad-sg">เติมสต็อก</button></div></div>`;tr(l);l.querySelectorAll('.ad-ta').forEach(t=>t.placeholder=trs(t.placeholder))}
async function adsLoad(){const l=$('#adsl');if(!l||!sb)return;try{ADS=await adFetch('id,name,image_url,stock,sold,options,option_stock');if(!ADS.length){l.innerHTML=hsEmpty;tr(l);return}if(!ADS.some(x=>x.id===AS.p))AS={p:ADS[0].id,o:0,t:''};adsR()}catch(_){adErr(l)}} // ADMIN
async function adsAdd(){const p=ADS.find(x=>x.id===AS.p),ta=$('.ad-sta'),ls=ta?adLines(ta.value):[],b=$('.ad-sg');if(!p||!ls.length||!sb||!isAdm())return;if(ls.length>500)return tpToast('ครั้งละไม่เกิน 500 ชิ้น');b.disabled=true;const oi=adsOpts(p).length?AS.o:null;
try{const r=await sb.from('stock_items').insert(ls.map(content=>({product_id:p.id,content,option_idx:oi})));if(r.error)throw r.error;
const g=await sb.from('products').select('stock,option_stock,sold').eq('id',p.id).single();if(g.data)Object.assign(p,g.data);AS.t='';adsR();okPop('เติมสต็อกสำเร็จ +'+ls.length);loadProds()}
catch(x){b.disabled=false;tpToast('เติมไม่สำเร็จ'+(x&&x.message?' ['+x.message+']':''))}} // ADMIN
document.addEventListener('click',e=>{if(e.target.closest('.ad-sg')){adsAdd();return}const o=e.target.closest('.as-op');if(o){AS.o=+o.dataset.i;adsR()}}); // ADMIN
document.addEventListener('change',e=>{if(e.target.id==='ass'){AS={p:e.target.value,o:0,t:''};adsR()}}); // ADMIN
// ===== หน้าส่งรหัสสินค้าอัตโนมัติ (หลังสั่งซื้อ) + ประวัติสั่งซื้อจริง =====
let DLV={},DLC=null;
const fdt=d=>{d=new Date(d);const z=n=>String(n).padStart(2,'0');return z(d.getHours())+':'+z(d.getMinutes())+' '+z(d.getDate())+'/'+z(d.getMonth()+1)+'/'+d.getFullYear()};
const ordD=o=>({order_id:o.id,items:o.items||[],total:o.total,name:o.product_name,label:o.option_label,qty:o.qty,created_at:o.created_at});
const dlvHtml=d=>{DLC=d;return `<div class="bc"><a href="#" data-v="home">หน้าหลัก</a> &nbsp;/&nbsp; <a href="#" data-v="hist-order">ประวัติสั่งซื้อ</a> &nbsp;/&nbsp; รหัสสินค้า</div>
<div class="dl-top"><div class="dl-ck"><svg viewBox="0 0 24 24"><path d="M5 12.5l4.5 4.5L19 7.5"/></svg></div><h1>สั่งซื้อสำเร็จ</h1><span class="or-no">เลขที่คำสั่งซื้อ #GX${String(d.order_id).replace(/-/g,'').slice(0,6).toUpperCase()}</span></div>
<div class="dl-card"><div class="dl-hd"><b>${esc(d.name)}</b>${d.label?`<em>${esc(d.label)}</em>`:''}<small>จำนวน ${d.qty} · ชำระ ${tpf(Number(d.total))} กีบ · ${fdt(d.created_at)}</small></div><div class="dl-sep"></div><div class="dl-lb">รหัสสินค้าของคุณ</div>${d.items.map((c,i)=>`<div class="dl-it" style="animation-delay:${i*70}ms"><span class="dl-n">${i+1}</span><code>${esc(c)}</code><button type="button" class="dl-cp" data-i="${i}">คัดลอก</button></div>`).join('')}</div>
<button class="tp-cta" id="dlall">คัดลอกทั้งหมด</button><a href="#" class="or-gh" data-v="home">กลับหน้าหลัก</a><p class="or-nt">บันทึกรหัสไว้ ดูย้อนหลังได้ในประวัติสั่งซื้อ</p>`};
views.deliver=m=>{const d=DLV[m];if(d)return dlvHtml(d);return `<div class="hs-em">กำลังโหลด...</div>${(setTimeout(()=>dlvFetch(m)),'')}`};
async function dlvFetch(m){if(!sb||CUR!=='deliver')return;try{const r=await sb.from('orders').select('*').eq('id',m).single();if(r.error||!r.data)throw 0;DLV[m]=ordD(r.data);app.innerHTML=dlvHtml(DLV[m]);tr(app)}catch(_){app.innerHTML=hsEmpty;tr(app)}}
function cpy(t){try{navigator.clipboard.writeText(t)}catch(_){const a=document.createElement('textarea');a.value=t;document.body.appendChild(a);a.select();try{document.execCommand('copy')}catch(_){}a.remove()}tpToast('คัดลอกแล้ว')}
document.addEventListener('click',e=>{const b=e.target.closest('.dl-cp'),a=e.target.closest('#dlall');if(!DLC||!(b||a))return;cpy(b?DLC.items[+b.dataset.i]:DLC.items.join('\n'))});
async function hsoLoad(){const l=$('#hso');if(!l||!sb||!USER)return;try{const r=await sb.from('orders').select('*').eq('user_id',USER.id).order('created_at',{ascending:false}).limit(50);if(r.error)throw r.error;const d=r.data||[];d.forEach(o=>DLV[o.id]=ordD(o));
l.innerHTML=d.map(o=>`<a href="#" class="tp-card hs-row" data-v="deliver" data-m="${o.id}"><span class="hs-ic"><svg viewBox="0 0 24 24">${HSI.b}</svg></span><div class="hs-m"><b>${esc(o.product_name)}${o.option_label?' · '+esc(o.option_label):''}</b><small>${fdt(o.created_at)}</small></div><div class="hs-r"><strong>-${tpf(Number(o.total))} กีบ</strong><span class="hs-bd ok">สำเร็จ</span></div></a>`).join('')||hsEmpty;tr(l)}catch(_){adErr(l)}}
// ===== ADMIN: จัดการหมวดหมู่ (ตาราง categories + คอลัมน์ products.category_id ใน Supabase PXPSHOP) =====
let ACL=[],ACP=[],AC={};
const acBc=t=>`<div class="bc"><a href="#" data-v="home">หน้าหลัก</a> &nbsp;/&nbsp; <a href="#" data-v="admin">ห้องแอดมิน</a> &nbsp;/&nbsp; ${t}</div>`;
const acBcF=t=>acBc('<a href="#" data-v="admin-cat">จัดการหมวดหมู่</a> &nbsp;/&nbsp; '+t);
const acErr=(l,x)=>{l.innerHTML='<div class="hs-em">โหลดไม่สำเร็จ'+(x&&x.message?' ['+esc(x.message)+']':'')+'</div>';tr(l)}; // ADMIN
// --- รายการหมวดหมู่ (เรียงลำดับ ▲▼ ได้)
views['admin-cat']=()=>acBc('จัดการหมวดหมู่')+`<h1 class="tp-h">จัดการหมวดหมู่</h1><button class="tp-cta" type="button" data-v="admin-catf" style="margin-bottom:16px">+ เพิ่มหมวดหมู่</button><div id="acl"><div class="hs-em">กำลังโหลด...</div></div>${(setTimeout(acLoad),'')}`; // ADMIN
async function acLoad(){const l=$('#acl');if(!l||!sb)return;try{const[c,p]=await Promise.all([sb.from('categories').select('*').order('sort_order',{ascending:true}).order('created_at',{ascending:true}),sb.from('products').select('id,name,image_url,category_id').order('created_at',{ascending:false})]);if(c.error)throw c.error;ACL=c.data||[];ACP=p.error?[]:(p.data||[]);acR()}catch(x){acErr(l,x)}} // ADMIN
function acR(){const l=$('#acl');if(!l)return;l.innerHTML=ACL.length?ACL.map((c,i)=>{const n=ACP.filter(p=>p.category_id===c.id).length;return `<div class="tp-card ad-sh ac-row"><a href="#" class="ac-main" data-v="admin-catf" data-m="${c.id}"><div class="ph">${c.image_url?`<img src="${esc(c.image_url)}" alt="">`:PH}</div><div><b>${esc(c.name)}</b><small>${n} สินค้า${c.is_active?'':' · ซ่อนอยู่'}</small></div></a><div class="ac-mv"><button type="button" data-i="${i}" data-d="-1" aria-label="up"${i?'':' disabled'}>▲</button><button type="button" data-i="${i}" data-d="1" aria-label="down"${i<ACL.length-1?'':' disabled'}>▼</button></div></div>`}).join(''):'<div class="hs-em">ยังไม่มีหมวดหมู่</div>';tr(l)} // ADMIN
async function acMove(i,d){const j=i+d;if(j<0||j>=ACL.length||!sb||!isAdm())return;[ACL[i],ACL[j]]=[ACL[j],ACL[i]];acR();
try{await Promise.all(ACL.map((c,k)=>[c,k]).filter(([c,k])=>c.sort_order!==k).map(([c,k])=>sb.from('categories').update({sort_order:k}).eq('id',c.id).then(r=>{if(r.error)throw r.error;c.sort_order=k})));loadCats()}
catch(x){tpToast('บันทึกไม่สำเร็จ'+(x&&x.message?' ['+x.message+']':''));acLoad()}} // ADMIN
// --- เพิ่ม/แก้ไขหมวดหมู่ (m = id หมวด → โหมดแก้ไข)
views['admin-catf']=m=>{const e=ACL.find(x=>x.id===m);
AC={f:null,id:e?e.id:null,old:e&&e.image_url||'',rm:false,act:e?e.is_active!==false:true,sel:new Set(e?ACP.filter(p=>p.category_id===e.id).map(p=>String(p.id)):[])};
const nm=id=>{const c=ACL.find(x=>x.id===id);return c?c.name:''};
return acBcF(e?'แก้ไขหมวดหมู่':'เพิ่มหมวดหมู่')+`<h1 class="tp-h">${e?'แก้ไขหมวดหมู่':'เพิ่มหมวดหมู่'}</h1>
<div class="tp-card"><h2>รูปหมวดหมู่</h2><label class="tp-up ac-up${AC.old?' has':''}"><input class="ac-fi" type="file" accept="image/*" hidden><img class="tp-pv" alt=""${AC.old?` src="${esc(AC.old)}"`:''}><button class="ac-rm" type="button" aria-label="x">✕</button><span class="tp-t">${adIc}<span>แตะเพื่อเลือกรูปหมวดหมู่</span></span></label></div>
<div class="tp-card"><h2>ชื่อหมวดหมู่</h2><input class="ad-in" id="acn" maxlength="40" autocomplete="off" placeholder="ชื่อหมวดหมู่" value="${e?esc(e.name):''}"></div>
<div class="tp-card"><div class="ad-sr"><div><h2>แสดงหมวดหมู่ในร้าน</h2><small>ปิดเพื่อซ่อนหมวดหมู่จากลูกค้า</small></div><button type="button" class="ac-sw${AC.act?' on':''}" role="switch" aria-checked="${AC.act}"><i></i></button></div></div>
<div class="tp-card"><h2>สินค้าในหมวดนี้</h2><small class="ac-hint">ติ๊กเลือกสินค้าที่ต้องการให้อยู่ในหมวดนี้</small><div class="ac-lst">${ACP.length?ACP.map(p=>{const id=String(p.id),o=p.category_id&&(!e||p.category_id!==e.id)?nm(p.category_id):'';return `<label class="ac-pr"><input type="checkbox" class="ac-ck" value="${esc(id)}"${AC.sel.has(id)?' checked':''}><div class="ph">${p.image_url?`<img src="${esc(p.image_url)}" alt="">`:PH}</div><span><b>${esc(p.name)}</b>${o?`<small>อยู่ในหมวด ${esc(o)}</small>`:''}</span></label>`}).join(''):'<div class="hs-em">ยังไม่มีสินค้า</div>'}</div></div>
<button class="tp-cta" id="acgo">บันทึกหมวดหมู่</button>${e?'<button class="ad-del" id="acdel" type="button">ลบหมวดหมู่</button>':''}`}; // ADMIN
function acImg(f){const im=new Image(),u=URL.createObjectURL(f);im.onload=()=>{const W=1200,H=Math.round(W/3.77),k=Math.max(W/im.width,H/im.height),c=document.createElement('canvas'),x=c.getContext('2d');c.width=W;c.height=H;x.fillStyle='#fff';x.fillRect(0,0,W,H);x.drawImage(im,(W-im.width*k)/2,(H-im.height*k)/2,im.width*k,im.height*k);c.toBlob(b=>{URL.revokeObjectURL(u);if(!b)return tpToast('ไฟล์รูปไม่ถูกต้อง');AC.f=b;AC.rm=false;$('.ac-up .tp-pv').src=URL.createObjectURL(b);$('.ac-up').classList.add('has')},'image/jpeg',.85)};im.onerror=()=>tpToast('ไฟล์รูปไม่ถูกต้อง');im.src=u} // ADMIN
async function acSave(){const g=$('#acgo'),name=$('#acn').value.trim(),lb='บันทึกหมวดหมู่';
if(!name)return tpToast('กรุณาใส่ชื่อหมวดหมู่');
if(ACL.some(c=>c.id!==AC.id&&c.name.trim().toLowerCase()===name.toLowerCase()))return tpToast('มีหมวดหมู่ชื่อนี้อยู่แล้ว');
if(!sb||!isAdm())return;g.disabled=true;g.textContent='กำลังบันทึก...';tr(g);
try{let url=AC.rm?null:(AC.old||null);if(AC.f){const path='cat_'+Date.now()+'_'+Math.random().toString(36).slice(2,8)+'.jpg',u=await sb.storage.from('product-images').upload(path,AC.f,{contentType:'image/jpeg'});if(u.error)throw u.error;url=sb.storage.from('product-images').getPublicUrl(path).data.publicUrl}
const row={name,image_url:url,is_active:AC.act};let id=AC.id,r;
if(id){r=await sb.from('categories').update(row).eq('id',id);if(r.error)throw r.error}
else{row.sort_order=ACL.length?Math.max(...ACL.map(c=>c.sort_order||0))+1:0;r=await sb.from('categories').insert(row).select('id').single();if(r.error)throw r.error;id=r.data.id}
const was=ACP.filter(p=>p.category_id===id).map(p=>String(p.id)),add=[...AC.sel].filter(x=>!was.includes(x)),rem=was.filter(x=>!AC.sel.has(x));
if(add.length){r=await sb.from('products').update({category_id:id}).in('id',add);if(r.error)throw r.error}
if(rem.length){r=await sb.from('products').update({category_id:null}).in('id',rem);if(r.error)throw r.error}
okPop(AC.id?'บันทึกหมวดหมู่สำเร็จ':'เพิ่มหมวดหมู่สำเร็จ');await loadProds();show('admin-cat')}
catch(x){g.disabled=false;g.textContent=lb;tr(g);tpToast('บันทึกไม่สำเร็จ'+(x&&x.message?' ['+x.message+']':''))}} // ADMIN
async function acDel(){if(!AC.id||!sb||!isAdm()||!confirm(trs('ลบหมวดหมู่นี้ใช่ไหม? สินค้าในหมวดจะไม่ถูกลบ')))return;try{const r=await sb.from('categories').delete().eq('id',AC.id);if(r.error)throw r.error;tpToast('ลบหมวดหมู่แล้ว');await loadProds();show('admin-cat')}catch(x){tpToast('ลบไม่สำเร็จ'+(x&&x.message?' ['+x.message+']':''))}} // ADMIN
// --- ตัวเลือกหมวดหมู่ในฟอร์มสินค้า (โหลดจากตาราง categories; ถ้าโหลดไม่ได้จะไม่ส่ง category_id เพื่อไม่ให้บันทึกสินค้าพัง)
async function acOpts(){const s=$('#adcat');if(!s||!sb)return;try{const r=await sb.from('categories').select('id,name,is_active').order('sort_order',{ascending:true}).order('created_at',{ascending:true});if(r.error)throw r.error;if(!AD.cat&&AD.id){const q=await sb.from('products').select('category_id').eq('id',AD.id).maybeSingle();if(q.data&&q.data.category_id)AD.cat=q.data.category_id}
s.innerHTML='<option value="">ไม่ระบุหมวดหมู่</option>'+(r.data||[]).map(c=>`<option value="${c.id}"${c.id===AD.cat?' selected':''}>${esc(c.name)}${c.is_active?'':' (ซ่อนอยู่)'}</option>`).join('');tr(s);AD.catOk=true}catch(_){}} // ADMIN
document.addEventListener('click',e=>{const t=e.target;
const mv=t.closest('.ac-mv button');if(mv){e.preventDefault();if(!mv.disabled)acMove(+mv.dataset.i,+mv.dataset.d);return}
if(t.closest('.ac-rm')){e.preventDefault();e.stopPropagation();AC.f=null;AC.rm=true;AC.old='';$('.ac-fi').value='';$('.ac-up .tp-pv').removeAttribute('src');$('.ac-up').classList.remove('has');return}
const sw=t.closest('.ac-sw');if(sw){AC.act=!AC.act;sw.classList.toggle('on',AC.act);sw.setAttribute('aria-checked',AC.act);return}
if(t.closest('#acdel')){acDel();return}
if(t.closest('#acgo'))acSave()}); // ADMIN
document.addEventListener('change',e=>{const t=e.target;if(t.classList.contains('ac-fi')){const f=t.files[0];if(f)acImg(f)}else if(t.classList.contains('ac-ck')){t.checked?AC.sel.add(t.value):AC.sel.delete(t.value)}else if(t.id==='adcat')AD.cat=t.value}); // ADMIN
// ===== ADMIN: จัดการบัญชี (ตาราง profiles, account_logs + ฟังก์ชัน admin_* ใน Supabase PXPSHOP) =====
// ทุกการเขียนข้อมูลผ่าน RPC (SECURITY DEFINER + is_admin()) ฝั่งฐานข้อมูล: admin_adjust_balance / admin_ban_user / admin_unban_user / admin_set_role / admin_reset_password / admin_add_note / admin_account_stats
