const AAPG=20,AAE={forbidden:'ไม่มีสิทธิ์ดำเนินการ',bad_amount:'จำนวนเงินไม่ถูกต้อง',not_found:'ไม่พบบัญชี',insufficient_balance:'ยอดเงินไม่พอให้หัก',cannot_self:'ทำรายการกับบัญชีตัวเองไม่ได้',target_is_admin:'แบนแอดมินไม่ได้ ต้องถอดสิทธิ์ก่อน',bad_duration:'ระยะเวลาไม่ถูกต้อง',bad_password:'รหัสผ่านต้อง 6-72 ตัวอักษร',bad_note:'บันทึกว่างหรือยาวเกิน 500 ตัวอักษร'};
let AA={q:'',f:'all',s:'new',pg:0,rows:[],more:false,busy:false,tok:0},AAT,AU=null,AUN={},AL={f:'all',pg:0,rows:[],more:false,tok:0};
const p2=n=>String(n).padStart(2,'0');
const aaDt=d=>{d=new Date(d);return isNaN(d)?'-':p2(d.getHours())+':'+p2(d.getMinutes())+' '+p2(d.getDate())+'/'+p2(d.getMonth()+1)+'/'+d.getFullYear()};
const aaD=d=>{d=new Date(d);return isNaN(d)?'-':p2(d.getDate())+'/'+p2(d.getMonth()+1)+'/'+d.getFullYear()};
const aaBanned=r=>!!(r&&r.banned_until&&new Date(r.banned_until)>new Date());
const aaPerm=r=>aaBanned(r)&&new Date(r.banned_until).getFullYear()>=2999;
const aaLeft=u=>{const m=Math.max(0,Math.round((new Date(u)-new Date())/60000)),d=Math.floor(m/1440),h=Math.floor(m%1440/60),n=m%60;return d?d+' วัน '+h+' ชม.':h?h+' ชม. '+n+' นาที':n+' นาที'};
const aaM=x=>{const m=(x&&x.message)||'';for(const k in AAE)if(m.includes(k))return AAE[k];return 'ไม่สำเร็จ'+(m?' ['+m+']':'')};
const aaRn=r=>r==='admin'?'แอดมิน':'สมาชิก';
const aaBc=t=>`<div class="bc"><a href="#" data-v="home">หน้าหลัก</a> &nbsp;/&nbsp; <a href="#" data-v="admin">ห้องแอดมิน</a> &nbsp;/&nbsp; ${t}</div>`;
async function aaRpc(fn,a){const r=await sb.rpc(fn,a);if(r.error)throw r.error;return r.data}
async function aaNames(ids){const n=[...new Set(ids.filter(i=>i&&!(i in AUN)))];if(!n.length)return;const r=await sb.from('profiles').select('id,username').in('id',n);(r.data||[]).forEach(x=>AUN[x.id]=x.username)}
const aaBdg=r=>(r.role==='admin'?'<em class="aa-b ad">แอดมิน</em>':'')+(aaBanned(r)?`<em class="aa-b bn">${aaPerm(r)?'ถูกแบนถาวร':'ถูกแบน'}</em>`:'');
// --- หน้ารายการบัญชี
views['admin-acc']=()=>aaBc('จัดการบัญชี')+`<h1 class="tp-h">จัดการบัญชี</h1><div class="aa-stats" id="aast">${'<div class="aa-st"><b>-</b><small>&nbsp;</small></div>'.repeat(4)}</div>
<div class="tp-card"><input class="ad-in" id="aaq" type="search" autocomplete="off" placeholder="ค้นหาชื่อผู้ใช้ หรือ ID" value="${esc(AA.q)}"><div class="aa-fl" id="aaf">${[['all','ทั้งหมด'],['ok','ปกติ'],['ban','ถูกแบน'],['adm','แอดมิน']].map(([k,l])=>`<button type="button" class="aa-chip${AA.f===k?' on':''}" data-af="${k}">${l}</button>`).join('')}</div>
<select class="ad-in" id="aas" style="margin-top:10px">${[['new','ใหม่สุด'],['bal','ยอดเงินมาก'],['name','ชื่อ A-Z']].map(([k,l])=>`<option value="${k}"${AA.s===k?' selected':''}>${l}</option>`).join('')}</select></div>
<button class="aa-more" type="button" data-aa="logs">ดูประวัติการดำเนินการทั้งหมด</button><div id="aal"></div>${(setTimeout(()=>{aaStats();aaLoad()}),'')}`; // ADMIN
async function aaStats(){if(!sb)return;const iso=new Date().toISOString(),t0=new Date();t0.setHours(0,0,0,0);const b=()=>sb.from('profiles').select('id',{count:'exact',head:true}),c=q=>q.then(r=>r.error?null:r.count);
const v=await Promise.all([c(b()),c(b().gte('created_at',t0.toISOString())),c(b().gt('banned_until',iso)),c(b().eq('role','admin'))]),L=['สมาชิกทั้งหมด','สมัครวันนี้','ถูกแบนอยู่','แอดมิน'],el=$('#aast');if(!el)return;
el.innerHTML=v.map((k,i)=>`<div class="aa-st"><b>${k==null?'-':tpf(k)}</b><small>${L[i]}</small></div>`).join('');tr(el)} // ADMIN
function aaQuery(){let q=sb.from('profiles').select('id,username,role,balance,created_at,banned_until,ban_reason'),t=AA.q.trim();const iso=new Date().toISOString();
if(t){if(/^[0-9a-f-]{32,36}$/i.test(t))q=q.eq('id',t);else{t=t.replace(/[^A-Za-z0-9_]/g,'').replace(/_/g,'\\_');if(t)q=q.ilike('username','%'+t+'%')}}
if(AA.f==='ban')q=q.gt('banned_until',iso);else if(AA.f==='ok')q=q.or('banned_until.is.null,banned_until.lte.'+iso);else if(AA.f==='adm')q=q.eq('role','admin');
if(AA.s==='bal')q=q.order('balance',{ascending:false});else if(AA.s==='name')q=q.order('username',{ascending:true});else q=q.order('created_at',{ascending:false});
return q.order('id')} // ADMIN
async function aaLoad(more){const l=$('#aal');if(!l||!sb)return;if(more&&AA.busy)return;const my=++AA.tok;AA.busy=true;if(!more){AA.pg=0;AA.rows=[];l.innerHTML='<div class="hs-em">กำลังโหลด...</div>';tr(l)}
try{const f=AA.pg*AAPG,r=await aaQuery().range(f,f+AAPG);if(r.error)throw r.error;if(my!==AA.tok)return;const d=r.data||[];AA.more=d.length>AAPG;AA.rows=AA.rows.concat(d.slice(0,AAPG));AA.pg++;aaR()}catch(x){if(my===AA.tok)acErr(l,x)}finally{if(my===AA.tok)AA.busy=false}} // ADMIN
const aaRow=r=>`<a href="#" class="tp-card ad-sh aa-row" data-v="admin-accu" data-m="${r.id}"><span class="aa-av${aaBanned(r)?' bn':''}">${esc((r.username||'?').charAt(0).toUpperCase())}</span><div><b>${esc(r.username)}${aaBdg(r)}</b><small>${tpf(Number(r.balance)||0)} กีบ · ${aaD(r.created_at)}</small></div><span class="ct-go"><svg viewBox="0 0 24 24"><path d="M9 5l7 7-7 7"/></svg></span></a>`;
