async function loadSettings(){try{if(sb){const r=await sb.rpc('public_settings');if(r.data)SET={...SET,...r.data}}}catch(_){}
ctsSync();TPMIN=SET.topup_min;TPMAX=SET.topup_max;TPQR=SET.topup_qr_url||'';brand(document)}
function brand(r){const n=SET.shop_name||'PXPSHOP';document.title=n;document.querySelectorAll('.dh b,.hd .hn').forEach(e=>{e.textContent=n});const w=document.createTreeWalker(r===document?document.body:r,NodeFilter.SHOW_TEXT);let x;while(x=w.nextNode())if(x.nodeValue.includes('PXPSHOP'))x.nodeValue=x.nodeValue.split('PXPSHOP').join(n);
if(SET.logo_url){document.querySelectorAll('.dh .ph,.alg,.hd .hl').forEach(e=>{if(!e.querySelector('img'))e.innerHTML='<img alt="" src="'+esc(SET.logo_url)+'" style="width:100%;height:100%;object-fit:cover;border-radius:inherit">'});let l=document.querySelector('link[rel=icon]');if(!l){l=document.createElement('link');l.rel='icon';document.head.appendChild(l)}l.href=SET.logo_url}
let a=$('#ann');if(!a){a=document.createElement('div');a.id='ann';a.className='ann';app.parentNode.insertBefore(a,app)}a.textContent=SET.announce_text||'';a.hidden=!(SET.announce_on&&SET.announce_text&&!maint())}
views.maint=()=>`<div class="mt"><div class="mt-ic">${SET.logo_url?`<img alt="" src="${esc(SET.logo_url)}">`:'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><path d="M14.7 6.3a4 4 0 00-5.4 5.4L3 18l3 3 6.3-6.3a4 4 0 005.4-5.4l-2.6 2.6-2.4-.6-.6-2.4z"/></svg>'}</div><h1>${esc(SET.maint_title||'ປິດປັບປຸງຊົ່ວຄາວ')}</h1><p>${esc(SET.maint_msg||'').replace(/\n/g,'<br>')}</p><a href="#" class="mt-ad" data-v="auth" data-m="login">ແອດມິນເຂົ້າສູ່ລະບົບ</a></div>`;
async function tpSend(){if(!sb)throw 0;const f=$('.tp-fi').files[0];let su=null;if(f){const pth=USER.id+'/'+Date.now()+'.jpg',u=await sb.storage.from('slips').upload(pth,f,{contentType:f.type||'image/jpeg'});if(u.error)throw u.error;su=sb.storage.from('slips').getPublicUrl(pth).data.publicUrl}
let h=null;try{if(f&&window.crypto&&crypto.subtle){const bf=await f.arrayBuffer();h=[...new Uint8Array(await crypto.subtle.digest('SHA-256',bf))].map(x=>x.toString(16).padStart(2,'0')).join('')}}catch(_){}
const r=await sb.rpc('submit_topup',{p_amount:tpA,p_slip:su,p_hash:h});if(r.error)throw r.error;return{...(r.data||{}),amount:tpA}}
// --- หน้าแอดมิน: ตั้งค่าร้าน (ข้อความหน้านี้เป็นภาษาไทย ไม่แปลเป็นลาว: ใช้ data-nt)
let SS={f:null,q:null,wh:'',ok:false};
// ===== ป็อปอัปติ๊กถูกตอนบันทึกสำเร็จ (ห้องแอดมิน) =====
function okPop(t){document.querySelectorAll('.ok-pop').forEach(x=>x.remove());const p=document.createElement('div');p.className='ok-pop';p.innerHTML='<div class="ok-card"><div class="ok-ic"><i class="ok-r"></i><i class="ok-r r2"></i><svg viewBox="0 0 24 24"><path d="M5.5 12.5l4.2 4.2L18.5 7.5"/></svg>'+[0,1,2,3,4,5,6,7].map(n=>'<b class="ok-d" style="--a:'+n*45+'deg"></b>').join('')+'</div><div class="ok-t"></div></div>';p.querySelector('.ok-t').textContent=trs(t);document.body.appendChild(p);requestAnimationFrame(()=>p.classList.add('on'));setTimeout(()=>{p.classList.remove('on');setTimeout(()=>p.remove(),350)},1700)}
const stT=t=>{let p=$('.tp-toast');if(!p){p=document.createElement('div');p.className='tp-toast';document.body.appendChild(p)}p.textContent=trs(t);p.classList.add('on');setTimeout(()=>p.classList.remove('on'),2400)};
views['admin-set']=()=>{SS={f:null,q:null,wh:'',ok:false,ci:[]};const S=SET,sw=(id,on)=>`<button type="button" class="ad-sw${on?' on':''}" id="${id}" role="switch" aria-checked="${!!on}"><i></i></button>`;
return `<div><div class="bc"><a href="#" data-v="home">หน้าหลัก</a> &nbsp;/&nbsp; <a href="#" data-v="admin">ห้องแอดมิน</a> &nbsp;/&nbsp; ตั้งค่าร้าน</div><h1 class="tp-h">ตั้งค่าร้าน</h1>
<div class="tp-card"><div class="ad-sr"><div><h2>เปิดเว็บให้ลูกค้า</h2><small id="stms">${S.maintenance?'ตอนนี้ปิดปรับปรุง: เฉพาะแอดมินเข้าได้':'ตอนนี้เว็บเปิดปกติ'}</small></div>${sw('stmt',!S.maintenance)}</div></div>
<div class="tp-card"><h2>ข้อความหน้าปิดปรับปรุง (ภาษาลาว)</h2><input class="ad-in" id="stmti" maxlength="60" style="padding-right:14px" value="${esc(S.maint_title)}"><textarea class="ad-ta" id="stmm" maxlength="300" style="margin-top:10px">${esc(S.maint_msg)}</textarea></div>
<div class="tp-card"><h2>โลโก้ร้าน</h2><label class="tp-up ad-up${S.logo_url?' has':''}"><input class="st-fi" type="file" accept="image/*" hidden><img class="tp-pv" alt=""${S.logo_url?` src="${esc(S.logo_url)}"`:''}><span class="tp-t"><span>แตะเพื่อเลือกโลโก้</span></span></label></div>
<div class="tp-card"><h2>รูปแบนเนอร์หน้าแรก</h2><label class="tp-up ad-up bn${S.banner_url?' has':''}"><input class="st-bn" type="file" accept="image/*" hidden><img class="tp-pv" alt=""${S.banner_url?` src="${esc(S.banner_url)}"`:''}><span class="tp-t"><span>แตะเพื่อเลือกรูปแบนเนอร์</span></span></label><small style="display:block;margin-top:8px;opacity:.7">ระบบจะปรับและครอปรูปให้พอดีกรอบอัตโนมัติ (แนะนำรูปแนวนอน)</small><button class="aa-btn full" type="button" id="stbr" style="margin-top:10px">ลบรูปแบนเนอร์</button></div>
<div class="tp-card"><h2>รูป QR โอนเงิน (แสดงในหน้าเติมเงิน)</h2><label class="tp-up ad-up sq${S.topup_qr_url?' has':''}"><input class="st-qr" type="file" accept="image/*" hidden><img class="tp-pv" alt=""${S.topup_qr_url?` src="${esc(S.topup_qr_url)}"`:''}><span class="tp-t"><span>แตะเพื่อเลือกรูป QR</span></span></label></div>
<div class="tp-card"><h2>ชื่อร้าน</h2><input class="ad-in" id="stn" maxlength="40" style="padding-right:14px" value="${esc(S.shop_name)}"></div>
<div class="tp-card"><h2>ลิงก์เว็บฮุก Discord (แจ้งเตือนเวลามีคนเติมเงิน)</h2><input class="ad-in" id="stwh" style="padding-right:14px" autocomplete="off" placeholder="https://discord.com/api/webhooks/..."><small style="display:block;margin-top:8px;opacity:.7">ลิงก์นี้เห็นเฉพาะแอดมิน</small><button class="aa-btn full" type="button" id="stwt" style="margin-top:10px">ส่งข้อความทดสอบ</button></div>
<div class="tp-card"><h2>ลิงก์เว็บไซต์ของร้าน (ทำให้มีลิงก์ ✅ ยืนยัน / ❌ ปฏิเสธ ใน Discord)</h2><input class="ad-in" id="stsite" autocomplete="off" inputmode="url" style="padding-right:14px" placeholder="https://your-site.com/"><small style="display:block;margin-top:8px;opacity:.7">ใส่ลิงก์หน้าเว็บจริง เช่น https://pxpshop.com/ — กดลิงก์ใน Discord แล้วจะเปิดหน้าตรวจสลิปทันที</small></div>
${ctForm()}
<div class="tp-card"><div class="ad-sr"><div><h2>แถบประกาศหน้าเว็บ</h2><small>แสดงข้อความด้านบนให้ลูกค้าเห็น</small></div>${sw('stan',S.announce_on)}</div><input class="ad-in" id="stat" maxlength="150" style="padding-right:14px;margin-top:12px" value="${esc(S.announce_text)}"></div>
<div class="tp-card"><h2>ยอดเติมเงิน (กีบ)</h2><div class="ad-pw"><input class="ad-in" id="stmin" inputmode="numeric" style="padding-right:70px" value="${S.topup_min}"><span>ขั้นต่ำ</span></div><div class="ad-pw" style="margin-top:10px"><input class="ad-in" id="stmax" inputmode="numeric" style="padding-right:70px" value="${S.topup_max}"><span>สูงสุด</span></div></div>
<button class="tp-cta" id="stgo">บันทึกการตั้งค่า</button>${(setTimeout(stWh),'')}</div>`};
async function stWh(){try{const r=await sb.from('shop_secrets').select('webhook_url,site_url').eq('id',1).maybeSingle();SS.wh=(r.data&&r.data.webhook_url)||'';SS.ok=true;const i=$('#stwh');if(i)i.value=SS.wh;SS.site=(r.data&&r.data.site_url)||'';const j=$('#stsite');if(j)j.value=SS.site||(/^https?:/.test(location.href)?location.origin+location.pathname:'')}catch(_){}}
function stLogo(f){const im=new Image(),u=URL.createObjectURL(f);im.onload=()=>{const k=Math.min(1,320/Math.max(im.width,im.height)),c=document.createElement('canvas');c.width=Math.round(im.width*k);c.height=Math.round(im.height*k);c.getContext('2d').drawImage(im,0,0,c.width,c.height);c.toBlob(b=>{URL.revokeObjectURL(u);if(!b)return stT('ไฟล์รูปไม่ถูกต้อง');SS.f=b;$('.ad-up .tp-pv').src=URL.createObjectURL(b);$('.ad-up').classList.add('has')},'image/png')};im.onerror=()=>stT('ไฟล์รูปไม่ถูกต้อง');im.src=u}
function stBn(f){const im=new Image(),u=URL.createObjectURL(f);im.onload=()=>{const R=3.94,W=Math.min(1600,im.width),H=Math.round(W/R);const c=document.createElement('canvas');c.width=W;c.height=H;let sw=im.width,sh=sw/R;if(sh>im.height){sh=im.height;sw=sh*R}const sx=(im.width-sw)/2,sy=(im.height-sh)/2;const x=c.getContext('2d');x.fillStyle='#fff';x.fillRect(0,0,W,H);x.drawImage(im,sx,sy,sw,sh,0,0,W,H);c.toBlob(b=>{URL.revokeObjectURL(u);if(!b)return stT('ไฟล์รูปไม่ถูกต้อง');SS.b=b;SS.br=false;const l=$('.bn');l.querySelector('.tp-pv').src=URL.createObjectURL(b);l.classList.add('has')},'image/jpeg',0.88)};im.onerror=()=>stT('ไฟล์รูปไม่ถูกต้อง');im.src=u}
function stQr(f){const im=new Image(),u=URL.createObjectURL(f);im.onload=()=>{const k=Math.min(1,900/Math.max(im.width,im.height)),c=document.createElement('canvas');c.width=Math.round(im.width*k);c.height=Math.round(im.height*k);const x=c.getContext('2d');x.fillStyle='#fff';x.fillRect(0,0,c.width,c.height);x.drawImage(im,0,0,c.width,c.height);c.toBlob(b=>{URL.revokeObjectURL(u);if(!b)return stT('ไฟล์รูปไม่ถูกต้อง');SS.q=b;const l=$('.sq');l.querySelector('.tp-pv').src=URL.createObjectURL(b);l.classList.add('has')},'image/png')};im.onerror=()=>stT('ไฟล์รูปไม่ถูกต้อง');im.src=u}
async function stSave(extra){const g=$('#stgo');if(!sb||!isAdm())return;const wh=$('#stwh').value.trim();if(wh&&!/^https:\/\/(discord(app)?\.com)\/api\/webhooks\/\d+\/[\w-]+/.test(wh))return stT('ลิงก์เว็บฮุกไม่ถูกต้อง');
const nm=$('#stn').value.trim();if(!nm)return stT('กรุณาใส่ชื่อร้าน');const mn=parseInt($('#stmin').value)||0,mx=parseInt($('#stmax').value)||0;if(mn<1||mx<mn)return stT('ยอดเติมเงินไม่ถูกต้อง');const cts=ctCollect();if(cts===null)return stT('ลิงก์ช่องทางติดต่อไม่ถูกต้อง');
g.disabled=true;g.textContent='กำลังบันทึก...';
try{let lg=SET.logo_url;if(SS.f){const pth='logo_'+Date.now()+'.png',u=await sb.storage.from('product-images').upload(pth,SS.f,{contentType:'image/png'});if(u.error)throw u.error;lg=sb.storage.from('product-images').getPublicUrl(pth).data.publicUrl}
let bn=SET.banner_url||null;if(SS.br)bn=null;if(SS.b){const pth='banner_'+Date.now()+'.jpg',u=await sb.storage.from('product-images').upload(pth,SS.b,{contentType:'image/jpeg'});if(u.error)throw u.error;bn=sb.storage.from('product-images').getPublicUrl(pth).data.publicUrl}
let qr=SET.topup_qr_url;if(SS.q){const pth='qr_'+Date.now()+'.png',u=await sb.storage.from('product-images').upload(pth,SS.q,{contentType:'image/png'});if(u.error)throw u.error;qr=sb.storage.from('product-images').getPublicUrl(pth).data.publicUrl}
const ctsv=await ctUpload(cts);const row={contacts:ctsv,shop_name:nm,logo_url:lg,banner_url:bn,topup_qr_url:qr,maint_title:$('#stmti').value.trim()||'ປິດປັບປຸງຊົ່ວຄາວ',maint_msg:$('#stmm').value.trim(),announce_on:$('#stan').classList.contains('on'),announce_text:$('#stat').value.trim(),topup_min:mn,topup_max:mx,maintenance:SET.maintenance,updated_at:new Date().toISOString()};
const r=await sb.from('shop_settings').update(row).eq('id',1).select('id');if(r.error||!r.data||!r.data.length)throw r.error||new Error('no_permission');
if(SS.ok){const w=await sb.from('shop_secrets').update({webhook_url:wh||null,site_url:(($('#stsite')||{}).value||'').trim()||null}).eq('id',1).select('id');if(w.error||!w.data||!w.data.length)throw w.error||new Error('no_permission')}
Object.assign(SET,row);ctsSync();SS.ci=[];TPMIN=mn;TPMAX=mx;TPQR=qr||'';SS.f=null;SS.q=null;SS.b=null;SS.br=false;brand(document);g.disabled=false;g.textContent='บันทึกการตั้งค่า';okPop('บันทึกสำเร็จ')}
catch(x){g.disabled=false;g.textContent='บันทึกการตั้งค่า';stT('บันทึกไม่สำเร็จ'+(x&&x.message?' ['+x.message+']':''))}}
async function stMaint(on){if(!sb||!isAdm())return;if(on&&!confirm('ปิดเว็บเพื่อปรับปรุง? ลูกค้าจะเข้าเว็บไม่ได้ (แอดมินยังใช้ได้ปกติ)'))return;const b=$('#stmt');b.disabled=true;
try{const r=await sb.from('shop_settings').update({maintenance:on,updated_at:new Date().toISOString()}).eq('id',1).select('id');if(r.error||!r.data||!r.data.length)throw r.error||new Error('no_permission');SET.maintenance=on;b.classList.toggle('on',!on);b.setAttribute('aria-checked',String(!on));$('#stms').textContent=on?'ตอนนี้ปิดปรับปรุง: เฉพาะแอดมินเข้าได้':'ตอนนี้เว็บเปิดปกติ';brand(document);okPop(on?'ปิดเว็บแล้ว':'เปิดเว็บแล้ว')}
catch(x){stT('ไม่สำเร็จ'+(x&&x.message?' ['+x.message+']':''))}b.disabled=false}
async function stTest(){const u=$('#stwh').value.trim();if(!/^https:\/\/(discord(app)?\.com)\/api\/webhooks\//.test(u))return stT('ใส่ลิงก์เว็บฮุกก่อน');try{const r=await fetch(u,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({content:'✅ ทดสอบแจ้งเตือนจาก '+SET.shop_name})});stT(r.ok?'ส่งแล้ว ดูใน Discord':'ส่งไม่สำเร็จ ('+r.status+')')}catch(_){stT('ส่งไม่สำเร็จ')}}
document.addEventListener('click',e=>{if(!isAdm())return;const t=e.target;if(t.closest('#stgo'))stSave();else if(t.closest('#stmt'))stMaint(SET.maintenance?false:true);else if(t.closest('#stwt'))stTest();else if(t.closest('#stbr')){SS.b=null;SS.br=true;const l=$('.bn');if(l){l.classList.remove('has');l.querySelector('.tp-pv').removeAttribute('src')}stT('จะลบรูปเมื่อกดบันทึกการตั้งค่า')}else if(t.closest('#stan'))t.closest('#stan').classList.toggle('on')}); // ADMIN
document.addEventListener('change',e=>{if(e.target.classList.contains('st-fi')&&e.target.files[0])stLogo(e.target.files[0]);if(e.target.classList.contains('st-qr')&&e.target.files[0])stQr(e.target.files[0]);if(e.target.classList.contains('st-bn')&&e.target.files[0])stBn(e.target.files[0])}); // ADMIN
