const ctForm=()=>{const A=SET.contacts||[];return '<div data-nt><div class="tp-card"><h2>ช่องทางติดต่อแอดมิน (สูงสุด 4 ช่อง)</h2><small style="display:block;opacity:.75;line-height:1.6">ช่องไหนไม่ใส่ลิงก์ = ไม่แสดงให้ลูกค้า ใส่แค่ Discord ช่องเดียว หน้าติดต่อแอดมินก็จะมีแค่ Discord</small></div>'+[0,1,2,3].map(i=>{const x=A[i]||{};return `<div class="tp-card ct-ed" data-ci="${i}"><h2>ช่องที่ ${i+1}</h2><select class="ad-in ct-t" style="padding-right:14px">${Object.entries(CTT).map(([k,v])=>`<option value="${k}"${(x.type||(['facebook','discord','telegram','phone'][i]))===k?' selected':''}>${v[0]}</option>`).join('')}</select><input class="ad-in ct-u" autocomplete="off" style="padding-right:14px;margin-top:10px" placeholder="ลิงก์ / เบอร์ / @ชื่อ (เว้นว่าง = ไม่แสดง)" value="${esc(x.url_raw||x.url||'')}"><input class="ad-in ct-n" maxlength="40" style="padding-right:14px;margin-top:10px" placeholder="ข้อความที่แสดง เช่น PXPSHOP หรือ @pxpshop" value="${esc(x.name||'')}"><textarea class="ad-ta ct-d" maxlength="200" style="margin-top:10px" placeholder="คำอธิบายช่องทางนี้ (ภาษาลาว, ไม่บังคับ)">${esc(x.desc||'')}</textarea><textarea class="ad-ta ct-w" maxlength="300" style="margin-top:10px" placeholder="ใช้ช่องทางนี้เมื่อ... (1 บรรทัดต่อ 1 ข้อ, ไม่บังคับ)">${esc((x.uses||[]).join('\n'))}</textarea><label class="tp-up ad-up ct-up${x.img?' has':''}" style="margin-top:10px"><input class="st-ct" data-i="${i}" type="file" accept="image/*" hidden><img class="tp-pv" alt=""${x.img?` src="${esc(x.img)}"`:''}><span class="tp-t"><span>แตะเพื่อเลือกรูปปก (ไม่บังคับ)</span></span></label><button type="button" class="aa-btn full ct-rm" data-i="${i}" style="margin-top:8px">ลบรูปปก</button></div>`}).join('')+'</div>'};
// เก็บค่าจากฟอร์ม: คืน array 4 ช่อง / null ถ้าลิงก์ผิด
function ctCollect(){const out=[];let bad=false;document.querySelectorAll('.ct-ed').forEach(c=>{const i=+c.dataset.ci,t=c.querySelector('.ct-t').value,raw=c.querySelector('.ct-u').value.trim(),u=ctUrl(t,raw);if(u===null)bad=true;
const old=((SET.contacts||[])[i]||{});out.push({type:t,url:u||'',url_raw:raw,name:c.querySelector('.ct-n').value.trim(),desc:c.querySelector('.ct-d').value.trim(),uses:c.querySelector('.ct-w').value.split('\n').map(x=>x.trim()).filter(Boolean).slice(0,5),img:SS.ci&&SS.ci[i]===0?'':old.img||'',_f:SS.ci&&SS.ci[i] instanceof Blob?SS.ci[i]:null})});return bad?null:out}
async function ctUpload(a){for(let i=0;i<a.length;i++){const x=a[i];if(x._f){const p='ct_'+Date.now()+'_'+i+'.jpg',u=await sb.storage.from('product-images').upload(p,x._f,{contentType:'image/jpeg'});if(u.error)throw u.error;x.img=sb.storage.from('product-images').getPublicUrl(p).data.publicUrl}delete x._f}return a}
function ctImg(f,i){const im=new Image(),u=URL.createObjectURL(f);im.onload=()=>{const k=Math.min(1,900/Math.max(im.width,im.height)),c=document.createElement('canvas');c.width=Math.round(im.width*k);c.height=Math.round(im.height*k);const x=c.getContext('2d');x.fillStyle='#fff';x.fillRect(0,0,c.width,c.height);x.drawImage(im,0,0,c.width,c.height);c.toBlob(b=>{URL.revokeObjectURL(u);if(!b)return stT('ไฟล์รูปไม่ถูกต้อง');SS.ci=SS.ci||[];SS.ci[i]=b;const l=document.querySelector(`.ct-ed[data-ci="${i}"] .ct-up`);l.querySelector('.tp-pv').src=URL.createObjectURL(b);l.classList.add('has')},'image/jpeg',.85)};im.onerror=()=>stT('ไฟล์รูปไม่ถูกต้อง');im.src=u}
document.addEventListener('change',e=>{if(e.target.classList.contains('st-ct')&&e.target.files[0]&&isAdm())ctImg(e.target.files[0],+e.target.dataset.i)}); // ADMIN
document.addEventListener('click',e=>{const b=e.target.closest('.ct-rm');if(!b||!isAdm())return;const i=+b.dataset.i;SS.ci=SS.ci||[];SS.ci[i]=0;const l=document.querySelector(`.ct-ed[data-ci="${i}"] .ct-up`);l.classList.remove('has');l.querySelector('.tp-pv').removeAttribute('src')}); // ADMIN

// ============================================================
// ===== ระบบอนุมัติเติมเงิน (เพิ่มใหม่) =====
//  • ลูกค้า: หน้ารอแอดมินยืนยัน (topup-wait) + หน้าสำเร็จ/ถูกปฏิเสธ + ประวัติเติมเงินจริง
//  • ADMIN: จัดการเติมเงิน (admin-topup) + หน้ารายละเอียด/ตรวจสลิป (admin-review) + ลิงก์ยืนยัน/ปฏิเสธจาก Discord (#review/<id>[/approve|/reject])
//  • ฝั่ง Supabase: ฟังก์ชัน submit_topup, admin_review_topup, admin_topup_list, admin_topup_get, admin_topup_counts, cancel_topup
// ============================================================
NEED.add('topup-wait');HSB.cancel='ຍົກເລີກແລ້ວ';
const Z2=n=>String(n).padStart(2,'0');
const ttDate=d=>{d=new Date(d);return Z2(d.getHours())+':'+Z2(d.getMinutes())+' '+Z2(d.getDate())+'/'+Z2(d.getMonth()+1)+'/'+d.getFullYear()};
const ttAgo=d=>{const s=Math.max(0,(Date.now()-new Date(d))/1000);if(s<60)return'เมื่อสักครู่';if(s<3600)return Math.floor(s/60)+' นาทีที่แล้ว';if(s<86400)return Math.floor(s/3600)+' ชม.ที่แล้ว';return Math.floor(s/86400)+' วันที่แล้ว'};
const ttNo=id=>'#'+String(id).slice(0,8).toUpperCase();
const ttSt={pending:'รอตรวจสอบ',approved:'อนุมัติแล้ว',rejected:'ปฏิเสธแล้ว',cancelled:'ลูกค้ายกเลิก'};
const ICO={ok:'<path d="M5 12.5l4.5 4.5L19 7.5"/>',no:'<path d="M6 6l12 12M18 6L6 18"/>',glass:'<path d="M6 3h12M6 21h12M7 3v3.500a5 5 0 002 4l3 2.500-3 2.500a5 5 0 00-2 4V21M17 3v3.500a5 5 0 01-2 4L12 13l3 2.500a5 5 0 012 4V21"/>',rf:'<path d="M20 11a8 8 0 10-2.300 5.700M20 4v7h-7"/>'};
function ttToast(t){let p=$('.tp-toast');if(!p){p=document.createElement('div');p.className='tp-toast';document.body.appendChild(p)}p.textContent=t;p.classList.add('on');setTimeout(()=>p.classList.remove('on'),2400)}
function ttSheet(h){document.querySelectorAll('.tp-ov,.tp-sh').forEach(x=>x.remove());document.body.insertAdjacentHTML('beforeend',`<div class="tp-ov"></div><section class="tp-sh" data-nt><div class="tp-gr"></div>${h}</section>`);document.body.style.overflow='hidden';const s=$('.tp-sh');s.offsetWidth;s.classList.add('on');$('.tp-ov').classList.add('on')}
function ttZoom(u){if(!u)return;document.body.insertAdjacentHTML('beforeend',`<div class="tt-lb"><img src="${esc(u)}" alt=""><button aria-label="ปิด">✕</button><a href="${esc(u)}" target="_blank" rel="noopener">เปิดรูปเต็ม</a></div>`)}
function ttBeep(){try{const a=new(window.AudioContext||window.webkitAudioContext)(),o=a.createOscillator(),g=a.createGain();o.connect(g);g.connect(a.destination);o.frequency.setValueAtTime(880,a.currentTime);o.frequency.setValueAtTime(1320,a.currentTime+.12);g.gain.setValueAtTime(.18,a.currentTime);g.gain.exponentialRampToValueAtTime(.001,a.currentTime+.4);o.start();o.stop(a.currentTime+.4)}catch(_){}}
const twConf=()=>'<div class="tw-cf">'+Array.from({length:34},(_,i)=>`<i style="--x:${Math.random()*100}%;--d:${(Math.random()*.9).toFixed(2)}s;--r:${Math.round(Math.random()*720-360)}deg;--c:${['#12b76a','#0071FF','#f79009','#ec4899','#8b5cf6','#22d3ee'][i%6]}"></i>`).join('')+'</div>';
function twCount(e,to){if(!e)return;const t0=performance.now();(function f(t){const k=Math.min(1,(t-t0)/1100);e.textContent=tpf(Math.round(to*(1-Math.pow(1-k,3))));if(k<1)requestAnimationFrame(f)})(t0)}

// ---------- ลูกค้า: หน้ารอแอดมินยืนยัน ----------
let TW={r:null,ch:null,iv:null,tk:null};
function twStop(){if(TW.ch){try{sb.removeChannel(TW.ch)}catch(_){}TW.ch=null}clearInterval(TW.iv);clearInterval(TW.tk);TW.iv=TW.tk=null}
views['topup-wait']=m=>`<div class="bc" data-nt><a href="#" data-v="home">ໜ້າຫຼັກ</a> &nbsp;/&nbsp; <a href="#" data-v="hist-topup">ປະຫວັດເຕີມເງິນ</a> &nbsp;/&nbsp; ສະຖານະຄຳຂໍ</div><div class="tw" id="tw" data-nt><div class="hs-em">ກຳລັງໂຫຼດ...</div></div>${(setTimeout(()=>twLoad(m)),'')}`;
async function twLoad(id){if(!sb||!USER)return;twStop();TW.r=null;try{const r=await sb.from('topup_requests').select('*').eq('id',id).maybeSingle();if(r.error||!r.data){$('#tw').innerHTML='<div class="hs-em">ບໍ່ພົບຄຳຂໍ</div>';return}twApply(r.data);
TW.ch=sb.channel('tw'+id).on('postgres_changes',{event:'UPDATE',schema:'public',table:'topup_requests',filter:'id=eq.'+id},p=>twApply(p.new)).subscribe();
TW.iv=setInterval(async()=>{if(CUR!=='topup-wait'){twStop();return}const q=await sb.from('topup_requests').select('*').eq('id',id).maybeSingle();if(q.data)twApply(q.data)},6000)}catch(_){const w=$('#tw');if(w)w.innerHTML='<div class="hs-em">ໂຫຼດບໍ່ສຳເລັດ</div>'}}
function twApply(r){if(CUR!=='topup-wait')return;const old=TW.r&&TW.r.status;TW.r=r;if(old===r.status)return;twRender(r);
if(r.status!=='pending'){clearInterval(TW.tk);if(old==='pending'){try{navigator.vibrate&&navigator.vibrate(r.status==='approved'?[80,60,80]:[200])}catch(_){}}
if(r.status==='approved')loadProf().then(()=>{anav();avr();const b=$('#twb');if(b)b.textContent=tpf(BAL)+' ກີບ'})}
if(r.status!=='pending'){clearInterval(TW.iv);if(TW.ch){try{sb.removeChannel(TW.ch)}catch(_){}TW.ch=null}}}
function twSteps(st){const a=st==='pending'?['done','act','']:st==='approved'?['done','done','done']:st==='rejected'?['done','done','bad']:['done','bad',''];const L=['ສົ່ງຄຳຂໍແລ້ວ','ແອດມິນກວດສະລິບ',st==='rejected'?'ບໍ່ຜ່ານການກວດ':'ເຕີມເງິນເຂົ້າບັນຊີ'];return `<div class="tw-steps">${a.map((c,i)=>`<div class="tw-s ${c}"><b>${c==='done'?'✓':c==='bad'?'✕':i+1}</b>${L[i]}</div>`).join('')}</div>`}
function twRender(r){const el=$('#tw');if(!el)return;const st=r.status,amt=Number(r.amount);
const rows=`<div class="tw-r"><span>ຍອດເຕີມເງິນ</span><b>${tpf(amt)} ກີບ</b></div><div class="tw-r"><span>ເລກທີ່ຄຳຂໍ</span><b>${ttNo(r.id)}</b></div><div class="tw-r"><span>ເວລາສົ່ງ</span><b>${ttDate(r.created_at)}</b></div>`;
const bt=(a,l,c)=>`<button class="${c||'tw-gh'}" ${a}>${l}</button>`;
let h='';
if(st==='pending')h=`<div class="tw-hero pend"><div class="tw-rad"><i></i><i></i><i></i><div class="tw-ic"><svg viewBox="0 0 24 24">${ICO.glass}</svg></div></div><h2>ກຳລັງລໍຖ້າແອດມິນກວດສອບ</h2><p>ພວກເຮົາໄດ້ຮັບສະລິບຂອງທ່ານແລ້ວ<br>ປົກກະຕິໃຊ້ເວລາບໍ່ເກີນ 10 ນາທີ</p><div class="tw-tm">ລໍຖ້າມາແລ້ວ <b id="twt">00:00</b></div></div>${twSteps(st)}<div class="tp-card">${rows}</div><p class="tw-nt">ໜ້ານີ້ອັບເດດອັດຕະໂນມັດ ທ່ານປິດໜ້າແລ້ວກັບມາເບິ່ງໃນປະຫວັດໄດ້</p><div class="tw-ac">${bt('data-v="home"','ກັບໜ້າຫຼັກ')}${bt('data-v="contact"','ຕິດຕໍ່ແອດມິນ')}${bt('data-twc="'+r.id+'"','ຍົກເລີກຄຳຂໍ','tw-gh dn')}</div>`;
else if(st==='approved')h=`<div class="tw-hero ok">${twConf()}<div class="tw-big ok"><svg viewBox="0 0 24 24">${ICO.ok}</svg></div><h2>ເຕີມເງິນສຳເລັດ!</h2><p>ແອດມິນຢືນຢັນແລ້ວ ຍອດເງິນຖືກເພີ່ມເຂົ້າບັນຊີຂອງທ່ານ</p><div class="tw-amt ok">+<span id="twa">0</span><small>ກີບ</small></div></div>${twSteps(st)}<div class="tp-card">${rows}<div class="tw-r"><span>ເວລາຢືນຢັນ</span><b>${ttDate(r.reviewed_at||r.created_at)}</b></div><div class="tw-r"><span>ຍອດເງິນຄົງເຫຼືອ</span><b id="twb">${tpf(BAL)} ກີບ</b></div></div><div class="tw-ac"><button class="tp-cta" data-v="list">ໄປເລືອກຊື້ສິນຄ້າ</button>${bt('data-v="home"','ກັບໜ້າຫຼັກ')}</div>`;
else if(st==='rejected')h=`<div class="tw-hero no"><div class="tw-big no"><svg viewBox="0 0 24 24">${ICO.no}</svg></div><h2>ຄຳຂໍຖືກປະຕິເສດ</h2><p>ແອດມິນບໍ່ສາມາດຢືນຢັນການເຕີມເງິນນີ້ໄດ້</p></div>${r.reject_reason?`<div class="tw-why"><small>ເຫດຜົນ</small><b data-r></b></div>`:''}${twSteps(st)}<div class="tp-card">${rows}<div class="tw-r"><span>ເວລາກວດສອບ</span><b>${ttDate(r.reviewed_at||r.created_at)}</b></div></div><p class="tw-nt">ຖ້າທ່ານໂອນເງິນແລ້ວ ກະລຸນາຕິດຕໍ່ແອດມິນພ້ອມສະລິບ</p><div class="tw-ac"><button class="tp-cta" data-v="topup">ເຕີມເງິນໃໝ່ອີກຄັ້ງ</button>${bt('data-v="contact"','ຕິດຕໍ່ແອດມິນ')}</div>`;
else h=`<div class="tw-hero"><div class="tw-big no" style="background:var(--sub);box-shadow:none"><svg viewBox="0 0 24 24">${ICO.no}</svg></div><h2>ຍົກເລີກຄຳຂໍແລ້ວ</h2><p>ທ່ານໄດ້ຍົກເລີກຄຳຂໍເຕີມເງິນນີ້</p></div><div class="tp-card">${rows}</div><div class="tw-ac"><button class="tp-cta" data-v="topup">ເຕີມເງິນໃໝ່</button>${bt('data-v="home"','ກັບໜ້າຫຼັກ')}</div>`;
el.innerHTML=h;const w=el.querySelector('[data-r]');if(w)w.textContent=r.reject_reason;
if(st==='approved')twCount($('#twa'),amt);
if(st==='pending'){const f=()=>{const e=$('#twt');if(!e){clearInterval(TW.tk);return}const s=Math.max(0,Math.floor((Date.now()-new Date(r.created_at))/1000));e.textContent=Z2(Math.floor(s/60))+':'+Z2(s%60)};f();clearInterval(TW.tk);TW.tk=setInterval(f,1000)}}
document.addEventListener('click',async e=>{const b=e.target.closest('[data-twc]');if(!b)return;if(!confirm('ຍົກເລີກຄຳຂໍນີ້ແມ່ນບໍ?'))return;b.disabled=true;try{const r=await sb.rpc('cancel_topup',{p_id:b.dataset.twc});if(r.error)throw r.error;TW.r=null;twLoad(b.dataset.twc)}catch(_){b.disabled=false;tpToast('ບໍ່ສຳເລັດ ອາດຖືກກວດສອບແລ້ວ');twLoad(b.dataset.twc)}});
// แถบเตือนในหน้าเติมเงิน ถ้ามีคำขอที่รอตรวจสอบอยู่
{const _tp=views.topup;views.topup=m=>_tp(m)+(setTimeout(twBanner),'')}
async function twBanner(){if(!sb||!USER||CUR!=='topup')return;const r=await sb.from('topup_requests').select('id,amount').eq('status','pending').order('created_at',{ascending:false}).limit(1);const d=r.data&&r.data[0];if(!d||CUR!=='topup')return;const h=$('.tp-h');if(h&&!$('.tw-bn'))h.insertAdjacentHTML('afterend',`<a href="#" class="tw-bn" data-v="topup-wait" data-m="${d.id}" data-nt><i></i><span>ມີຄຳຂໍເຕີມເງິນ ${tpf(+d.amount)} ກີບ ກຳລັງລໍແອດມິນ</span><b>ເບິ່ງ ›</b></a>`)}
// ประวัติเติมเงิน = ข้อมูลจริงจาก Supabase (แตะเพื่อดูสถานะ)
views['hist-topup']=()=>hsPage('ดูประวัติเติมเงิน','ดูประวัติเติมเงิน','<div id="hst"><div class="hs-em">กำลังโหลด...</div></div>')+(setTimeout(hstLoad),'');
async function hstLoad(){const l=$('#hst');if(!l||!sb||!USER)return;try{const r=await sb.from('topup_requests').select('id,amount,status,created_at').order('created_at',{ascending:false}).limit(50);if(r.error)throw r.error;const M={approved:'ok',pending:'wait',rejected:'no',cancelled:'cancel'};l.innerHTML=(r.data||[]).map(x=>`<a href="#" class="hs-lnk" data-v="topup-wait" data-m="${x.id}">${hsRow(HSI.w,'เติมเงินผ่าน QR',ttDate(x.created_at),'+'+tpf(Number(x.amount))+' กีบ',M[x.status]||'wait')}</a>`).join('')||hsEmpty;tr(l)}catch(_){l.innerHTML='<div class="hs-em">โหลดไม่สำเร็จ</div>';tr(l)}}

// ---------- ADMIN: จัดการเติมเงิน ----------
let TT={st:'pending',q:'',list:[],cnt:{},ch:null,iv:null,prevP:null,cur:null,act:null};
function adStop(){if(TT.ch){try{sb.removeChannel(TT.ch)}catch(_){}TT.ch=null}clearInterval(TT.iv);TT.iv=null;TT.prevP=null;document.title=SET.shop_name||'PXPSHOP'}
const ttBc=t=>`<div class="bc"><a href="#" data-v="home">หน้าหลัก</a> &nbsp;/&nbsp; <a href="#" data-v="admin">ห้องแอดมิน</a> &nbsp;/&nbsp; ${t}</div>`;
views['admin-topup']=()=>`<div data-nt>${ttBc('จัดการเติมเงิน')}<div class="tt-hd"><h1 class="tp-h">จัดการเติมเงิน</h1><button class="tt-rf" id="ttrf" aria-label="รีเฟรช"><svg viewBox="0 0 24 24">${ICO.rf}</svg></button></div><div class="tt-live"><i></i><span>รับคำขอแบบเรียลไทม์ · มีเสียงแจ้งเตือนเมื่อมีคำขอใหม่</span></div><div class="tt-st" id="ttst"></div><div class="tt-tabs" id="tttabs"></div><label class="tt-sr"><input id="ttq" type="search" autocomplete="off"></label><div id="ttl"><div class="hs-em">กำลังโหลด...</div></div></div>${(setTimeout(ttInit),'')}`; // ADMIN
function ttInit(){if(!sb||!isAdm())return;adStop();TT.st='pending';TT.q='';ttLoad();TT.ch=sb.channel('ttl').on('postgres_changes',{event:'*',schema:'public',table:'topup_requests'},()=>ttLoad(true)).subscribe();TT.iv=setInterval(()=>{if(CUR!=='admin-topup'){adStop();return}ttLoad(true)},15000);const q=$('#ttq');if(q)q.placeholder='ค้นหาชื่อผู้ใช้ / เลขคำขอ'}
async function ttLoad(silent){const l=$('#ttl');if(!l||!sb||!isAdm())return;const rf=$('#ttrf');if(rf&&!silent){rf.classList.add('sp');setTimeout(()=>rf.classList.remove('sp'),800)}
try{const[a,c]=await Promise.all([sb.rpc('admin_topup_list',{p_status:TT.st,p_limit:100}),sb.rpc('admin_topup_counts')]);if(a.error)throw a.error;TT.list=a.data||[];TT.cnt=c.data||{};const p=+TT.cnt.pending||0;if(TT.prevP!=null&&p>TT.prevP){ttBeep();ttToast('💰 มีคำขอเติมเงินใหม่ '+(p-TT.prevP)+' รายการ')}TT.prevP=p;document.title=(p?'('+p+') ':'')+(SET.shop_name||'PXPSHOP');ttDraw()}catch(x){l.innerHTML='<div class="hs-em">โหลดไม่สำเร็จ'+(x&&x.message?' ['+esc(x.message)+']':'')+'</div>'}}
const ttBadge=s=>`<span class="tt-bd ${s}">${ttSt[s]||s}</span>`;
